# Check if grid has any symmetry (horizontal, vertical, rotational)
def is_symmetric(grid, direction='vertical'):
    if direction == 'vertical':
        return np.allclose(grid[:, :-1], np.flipud(grid[:, 1:]))
    elif direction == 'horizontal':
        return np.allclose(grid[:-1, :], np.flipud(grid[1:, :]))
