# Apply the CORRECT transformation rule based on memory findings:
# "8s transform to 2 ONLY if they form a VERTICAL component of size exactly 2"

test_input = grid_in  # Using grid_in variable

def get_connected_components_8(grid):
    """Get connected components of color 8 using 8-connectivity"""
    rows = len(grid)
    cols = len(grid[0])

    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8 and not visited[r][c]:
                comp = []
                stack = [(r, c)]

                while stack:
                    cr, cc = stack.pop()
                    if visited[cr][cc]:
                        continue
                    visited[cr][cc] = True

                    comp.append((cr, cc))

                    # 8-connectivity neighbors
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr][nc] == 8 and not visited[nr][nc]:
                                    stack.append((nr, nc))

                components.append(comp)

    return components

def is_vertical_pair(component):
    """Check if component is a vertical pair (size 2, same column)"""
    if len(component) != 2:
        return False

    (r1, c1), (r2, c2) = sorted(component)

    # Must be same column
    if c1 != c2:
        return False

    # Must be vertically adjacent
    return abs(r1 - r2) == 1

def is_horizontal_pair(component):
    """Check if component is a horizontal pair"""
    if len(component) != 2:
        return False

    (r1, c1), (r2, c2) = sorted(component)

    # Must be same row
    if r1 != r2:
        return False

    # Must be horizontally adjacent
    return abs(c1 - c2) == 1

components = get_connected_components_8(test_input)
print(f"Found {len(components)} background (8) components")

vertical_pairs = []
horizontal_pairs = []
other_comps = []

for i, comp in enumerate(components):
    if is_vertical_pair(comp):
        vertical_pairs.append(comp)
    elif is_horizontal_pair(comp):
        horizontal_pairs.append(comp)
    else:
        other_comps.append(comp)

