import json

workspace = '/home/ubuntu/runs/rt/dagger-u1-final/play/users/u000/system/state/workspace'
arc_task_path = f'{workspace}/arc_task.json'

with open(arc_task_path, 'r') as f:
    task_data = json.load(f)

# Each row in input/output is a JSON string representation of an array
input_grid = [[int(x) for x in row.strip('[]').split(',')] for row in task_data['input']]
output_grid = [[int(x) for x in row.strip('[]').split(',')] for row in task_data['output']]

print(f"Input shape: {len(input_grid)}x{len(input_grid[0])}")
print(f"Output shape: {len(output_grid)}x{len(output_grid[0])}")

def most_frequent(grid):
    counts = {}
    for row in grid:
        for cell in row:
            c = int(cell)
            counts[c] = counts.get(c, 0) + 1
    return max(counts.items(), key=lambda x: x[1])[0]

bg_input = most_frequent(input_grid)
bg_output = most_frequent(output_grid)

print(f"\nBackground color in input: {bg_input}")
print(f"Background color in output: {bg_output}")

def unique_colors(grid):
    colors = set()
    for row in grid:
        for cell in row:
            colors.add(int(cell))
    return sorted(colors)

colors_input = unique_colors(input_grid)
colors_output = unique_colors(output_grid)

print(f"Colors in input: {colors_input}")
print(f"Colors in output: {colors_output}")

# Find all differences
