# Let me check if there are isolated vertical pairs in main task that should swap colors
import json, os
from collections import defaultdict

supervisor_path = '/tmp'

with open(os.path.join(supervisor_path, 'arc_request.json'), 'r') as f:
    req_data = json.load(f)

user_msg = req_data['messages'][1]['content']
input_lines = user_msg.split('INPUT GRID (25 rows, 29 columns):')[1].strip().split('\n')
input_grid = [[int(x) for x in line.strip('[]').split(',')] for line in input_lines]

bg_color = 8

# Find all isolated vertical pairs (two cells of same color adjacent vertically, 
# but NO neighbors of same color horizontally or diagonally)
print("=== Finding Isolated Vertical Pairs ===")

def get_color(r, c):
    if 0 <= r < len(input_grid) and 0 <= c < len(input_grid[0]):
        return int(input_grid[r][c])
    return bg_color

def is_isolated_vertical_pair(grid, r1, c, r2, target_color):
    """Check if cells at (r1,c) and (r2,c) form an isolated vertical pair"""
    # First verify both cells have the target color
    if grid[r1][c] != target_color or grid[r2][c] != target_color:
        return False

    # Check if each cell has any same-color neighbor OTHER than its paired neighbor
    for offset_r in [-1, 0, 1]:
        for offset_c in [-1, 0, 1]:
            # Skip checking the paired cell
            if (offset_r == r2-r1 and offset_c == 0) or (offset_r == r1-r2 and offset_c == 0):
                continue

            nr = r1 + offset_r
            nc = c + offset_c

            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == target_color:
                    return False

    return True

# Search for isolated vertical pairs
vertical_pairs = []
for c in range(len(input_grid[0])):
    for r in range(len(input_grid) - 1):
        cell_above = get_color(r, c)
        cell_below = get_color(r+1, c)

        if cell_above == cell_below and cell_above != bg_color:
            # Check if isolated
            if is_isolated_vertical_pair(input_grid, r, c, r+1, cell_above):
                vertical_pairs.append((r, c, cell_above))

print(f"Found {len(vertical_pairs)} isolated vertical pairs:")
for r, c, color in vertical_pairs[:20]:
    print(f"  ({r},{c}) color={color}")

if not vertical_pairs:
    print("None found!")

# Also check for isolated HORIZONTAL pairs
print("\n=== Finding Isolated Horizontal Pairs ===")
horizontal_pairs = []
for r in range(len(input_grid)):
    for c in range(len(input_grid[0]) - 1):
        cell_left = get_color(r, c)
        cell_right = get_color(r, c+1)

        if cell_left == cell_right and cell_left != bg_color:
            # Check isolation
            isolated = True
            for offset_r in [-1, 0, 1]:
                for offset_c in [-2, -1, 0, 1, 2]:
                    if offset_r == 0 and abs(offset_c) == 1:
                        continue
                    nr, nc = r + offset_r, c + offset_c
                    if 0 <= nr < len(input_grid) and 0 <= nc < len(input_grid[0]):
                        if input_grid[nr][nc] == cell_left:
                            isolated = False
                            break
                if not isolated:
                    break
            if isolated:
                horizontal_pairs.append((r, c, cell_left))

print(f"Found {len(horizontal_pairs)} isolated horizontal pairs:")
for r, c, color in horizontal_pairs[:20]:
    print(f"  ({r},{c}) color={color}")

